#include <basalt/optimization/spline_linearize.h>
#include <basalt/optimization/spline_optimize.h>
#include <nlohmann/json.hpp>
#include <iostream>
using Json=nlohmann::json;
template<class M>Json values(const M&m){Json result=Json::array();for(int r=0;r<m.rows();++r)for(int c=0;c<m.cols();++c)result.push_back(m(r,c));return result;}
template<class M>Json sparse(const M&m){Json result=Json::array();for(int r=0;r<m.rows();++r)for(int c=0;c<m.cols();++c)if(m(r,c)!=0.)result.push_back({r,c,m(r,c)});return result;}
template<class T>Json run(const T&measurement,basalt::Se3Spline<4,double>&spline,const basalt::LinearizeBase<double>::CalibCommonData&common){Eigen::aligned_deque<T>data;data.push_back(measurement);using Iterator=typename Eigen::aligned_deque<T>::const_iterator;tbb::blocked_range<Iterator>range(data.cbegin(),data.cend());basalt::LinearizeSplineOpt<4,double,basalt::DenseAccumulator<double>>linearization(72,&spline,common);linearization(range);basalt::ComputeErrorSplineOpt<4,double>error(72,&spline,common);error(range);return {{"h",sparse(linearization.accum.getH())},{"b",values(linearization.accum.getB())},{"error",linearization.error},{"reprojection_error",linearization.reprojection_error},{"num_points",linearization.num_points},{"computed_error",error.error}};}
int main(){basalt::Se3Spline<4,double>spline(20000000,1000000000);for(int i=0;i<4;++i)spline.knotsPushBack(Sophus::SE3d(Sophus::SO3d::exp(Eigen::Vector3d(.025*i,-.015*i*i,.01*(i%3))),Eigen::Vector3d(.125*i,.0625*i*i,-.03125*i)));basalt::Calibration<double>calibration;auto camera=basalt::GenericCamera<double>::fromString("pinhole");camera.setFromInit(Eigen::Vector4d(320,315,320,240));calibration.intrinsics={camera};calibration.T_i_c={Sophus::SE3d(Sophus::SO3d(),Eigen::Vector3d(.125,0.,0.))};basalt::MocapCalibration<double>mocap;mocap.T_moc_w=Sophus::SE3d(Sophus::SO3d(),Eigen::Vector3d(.2,-.1,.3));mocap.T_i_mark=Sophus::SE3d(Sophus::SO3d(),Eigen::Vector3d(.05,.1,0.));Eigen::aligned_vector<Eigen::Vector4d>corners={Eigen::Vector4d(-.25,-.25,3,1),Eigen::Vector4d(.25,-.25,3,1),Eigen::Vector4d(.25,.25,3,1)};std::vector<size_t>extrinsic={48},intrinsic={54};Eigen::Vector3d gravity(0,0,-9.81);basalt::LinearizeBase<double>::CalibCommonData common;common.calibration=&calibration;common.mocap_calibration=&mocap;common.aprilgrid_corner_pos_3d=&corners;common.offset_T_i_c=&extrinsic;common.offset_intrinsics=&intrinsic;common.bias_block_offset=24;common.mocap_block_offset=58;common.g=&gravity;common.pose_var_inv=2.;common.accel_var_inv<<2,3,4;common.gyro_var_inv<<5,6,7;common.mocap_var_inv=3.;common.huber_thresh=2.;basalt::PoseData pose;pose.timestamp_ns=1007000000;pose.data=Sophus::SE3d(Sophus::SO3d::exp(Eigen::Vector3d(.1,-.2,.3)),Eigen::Vector3d(.2,.3,-.1));basalt::AccelData accel;accel.timestamp_ns=pose.timestamp_ns;accel.data<<.1,-.2,.3;basalt::GyroData gyro;gyro.timestamp_ns=pose.timestamp_ns;gyro.data=accel.data;basalt::MocapPoseData marker;marker.timestamp_ns=pose.timestamp_ns;marker.data=pose.data;basalt::AprilgridCornersData image;image.timestamp_ns=pose.timestamp_ns;image.cam_id=0;image.corner_id={0,1,2};image.corner_pos={Eigen::Vector2d(300,200),Eigen::Vector2d(350,205),Eigen::Vector2d(355,250)};Json result=Json::array();for(bool full:{false,true}){common.opt_intrinsics=full;common.opt_cam_time_offset=full;common.opt_imu_scale=full;common.opt_g=full;result.push_back({{"full",full},{"pose",run(pose,spline,common)},{"accel",run(accel,spline,common)},{"gyro",run(gyro,spline,common)},{"mocap",run(marker,spline,common)},{"aprilgrid",run(image,spline,common)}});}std::cout<<result.dump()<<'\n';}
